#include <stdio.h>

int lowbit(int x) {
    return x & (-x);
}

int NumberOf1(int x) {
    int count = 0;
    while (x) {
        x -= lowbit(x);
        count++;
    }
    return count;
}

int main() {
    int n;
    scanf("%d",&n);
    printf("%d\n",NumberOf1(n));
  return 0;
}

#include <iostream>

