#define N 16

//用打表法计算log2(n)的值
int log[1<<N];
//建表
void BuildLogTable(int n){
    for(int i=0;i<=n;i++) log[1<<i]=i;
}

//lowbit函数
int lowbit(int x){
    return x&(-x);
}

//查表
int Log2(int n){
    return log[lowbit(n)];
}

int main(){
    BuildLogTable(N);
    int n;
    cin>>n;
    cout<<Log2(n)<<endl;
    return 0;
}

