#include <iostream>
using namespace std;
const int MAXN = 100005;

int n;
int arr[MAXN];
int temp[MAXN];
long long ans=0;                                 //全局变量，记录逆序对的个数
void merge_sort(int arr[],int left,int right)    //用归并排序计算逆序对个数
{
    if(left>=right) return;
    int mid=(left+right)/2;
    merge_sort(arr,left,mid);
    merge_sort(arr,mid+1,right);

    int k=0;
    int i=left,j=mid+1;
    while(i<=mid&&j<=right){
        if(arr[i]<=arr[j]) temp[k++]=arr[i++];
        else{ 
            temp[k++]=arr[j++];
            ans+=mid-i+1;                         //统计逆序对的个数
        }              
    }
    while(i<=mid) temp[k++]=arr[i++];
    while(j<=right) temp[k++]=arr[j++];
    for(int i=left,j=0;i<=right;i++,j++)
        arr[i]=temp[j];
}

int main(){
    ios::sync_with_stdio(false);   
    cin>>n;
    for(int i=0;i<n;i++){
        cin>>arr[i];
    }
    merge_sort(arr,0,n-1);
    cout<<ans<<endl;                
    return 0;
}

#include <iostream>
using namespace std;

const int N = 100005;
int arr[N];

int quickSelect(int left, int right, int k) {
    if (left == right) return arr[left];
    int pivot = arr[(left + right) / 2];
    int i = left, j = right;
    while (i <= j) {
        while (arr[i] < pivot) i++;
        while (arr[j] > pivot) j--;
        if (i <= j) swap(arr[i++], arr[j--]);
    }
    int leftLen = j - left + 1;
    if (k <= leftLen) return quickSelect(left, j, k);
    else return quickSelect(i, right, k - (i - left));
}

int main() {
    ios::sync_with_stdio(false);
    int n, k;
    cin >> n >> k;
    for (int i = 0; i < n; i++) cin >> arr[i];
    cout << quickSelect(0, n - 1, k) << endl;
    return 0;
}

