#include <iostream>
using namespace std;

const int N = 100005;
int arr[N];

// 找左边界：第一个 >= target 的位置
int bsearch1(int n, int target) {
    int left = 0, right = n;
    while (left < right) {
        int mid = left + (right - left) / 2;
        if (arr[mid] >= target) right = mid;
        else left = mid + 1;
    }
    return (left < n && arr[left] == target) ? left : -1;
}

// 找右边界：最后一个 <= target 的位置
int bsearch2(int n, int target) {
    int left = 0, right = n;
    while (left < right) {
        int mid = left + (right - left) / 2;
        if (arr[mid] <= target) left = mid + 1;
        else right = mid;
    }
    return (left > 0 && arr[left - 1] == target) ? left - 1 : -1;
}

int main() {
    int n, target;
    cin >> n >> target;
    for (int i = 0; i < n; i++) cin >> arr[i];
    int l = bsearch1(n, target);
    int r = bsearch2(n, target);
    if (l == -1) cout << "-1 -1" << endl;
    else cout << l << " " << r << endl;
    return 0;
}

#include <iostream>
