double f(double x) {
    return x * x * x - 5 * x * x + 10 * x - 80;
}

int main() {
    double left = 0, right = 100;
    double eps = 1e-11;
    while (right - left > eps) {
        double mid = (left + right) / 2;
        if (f(mid) == 0) {
            left = right = mid;
            break;
        } else if (f(mid) > 0) {
            right = mid;
        } else {
            left = mid;
        }
    }
    cout << fixed << setprecision(9) << left << endl;
    return 0;
}

