const int N = 100005;
int a[N];
int n, m;

bool check(int budget) {
    int groups = 1, sum = 0;
    for (int i = 0; i < n; i++) {
        if (sum + a[i] > budget) {
            groups++;
            sum = a[i];
            if (groups > m) return false;
        } else {
            sum += a[i];
        }
    }
    return true;
}

