#define maxn 10005

const double pi=acos(-1.0);
const double eps=1e-6;

int n;
long long f;
double v[maxn];

bool check_cake(double current_cake){
    if(current_cake<eps) return true;
    long long cnt=0;
    for(int i=0;i<n;i++){
        if(v[i]<current_cake) continue;
        cnt+=(long long)(v[i]/current_cake);
        if(cnt>=f) return true;
    }
    return false;
}

double bsearch(double l,double r){
    while(r-l>eps){
        double mid=(l+r)/2;
        if(check_cake(mid)) l=mid;
        else r=mid;
    }
    return l;
}

int main(){
    cin>>n>>f;
    f++;    
    long long r;
    for(int i=0;i<n;i++){
        cin>>r;
        v[i]=1.0*r*r;
    }
    sort(v,v+n);
    double min_Cake=0.0;
    double max_Cake=v[n-1];
    double result=bsearch(min_Cake,max_Cake);
    printf("%.3lf\n",result*pi);
    return 0;
}

