using namespace std;

static const long long MOD = 1000000007LL;

int main(){
    int n;
    string expr;
    cin >> n >> expr;

    long long sum = 0;
    long long term = expr[0] - '0';

    for(int i = 1; i < 2 * n - 1; i += 2){
        char op = expr[i];
        long long value = expr[i + 1] - '0';
        if(op == '*'){
            term = (term * value) % MOD;
        }else{
            sum = (sum + term) % MOD;
            term = value;
        }
    }

    sum = (sum + term) % MOD;
    cout << sum << '\n';
    return 0;
}

