#include <iostream>
#include <cstring>
#include <bitset>
using namespace std;

int main(){
    string line;
    bitset<32> lock;
    int minTime=1<<30;
    cin>>line;
    bitset<32> sourceLock(line);
    cin>>line;
    bitset<32> targetLock(line);
    int n=line.size();
    //枚举第一个按钮是否按下的两种情况
    for(int p=0;p<2;++p){
        lock=sourceLock;
        int times=0;
        int nextButton=p;
        for(int i=0;i<n;++i){
            if(nextButton==1){
                ++times;
                if(i>0) lock.flip(i-1);
                lock.flip(i);
                if(i<n-1) lock.flip(i+1);
            }
            if(lock[i]!=targetLock[i]){
                nextButton=1;
            }
            else nextButton=0;
        }
        if(lock==targetLock) 
        {
            minTime=min(minTime,times);
            break;
        }        
    }
    if(minTime==1<<30) cout<<"impossible"<<endl;
    else cout<<minTime<<endl;
    return 0;
}

#include <iostream>
#include <cstring>
#include <bitset>
#include <memory>
using namespace std;

bitset<6> source[5],
light[5],res[5],line;

int main(){
    int T;
    cin>>T;
    int t=T;
    while(T--){
        for(int i=0;i<5;i++){
          for(int j=0;j<6;j++){
            int x;
            cin>>x;
            source[i].set(j,x);
          }
        }
        //遍历首行开关灯的64种情况
        for(int n=0;n<64;n++){
            for(int i=0;i<5;i++){
                light[i]=source[i];
            }
            line=n;

            for(int i=0;i<5;i++){  
                res[i]=line;
                for(int j=0;j<6;j++){
                    if(line.test(j)){                //判断当前开关是否被按下
                        if(j>0) light[i].flip(j-1);  //改左灯
                        light[i].flip(j);            //改当前灯
                        if(j<5) light[i].flip(j+1);  //改右灯
                    }
                }
                if(i<4) light[i+1]^=line;  //改下一行灯的状态
                line=light[i];             //第i+1行开关方案和第i行灯的状态相同
            }

            if(light[4].none()){           //判断最后一行灯是否全灭
                cout<<"PUZZLE #"<<t-T<<endl;
                for(int i=0;i<5;i++){
                    for(int j=0;j<6;j++){
                        cout<<res[i].test(j)<<" ";
                    }
                    cout<<endl;
                }
                break;
            }
        } 
    }
    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

int main() {
	int state0[9];
	for (int i = 0; i < 9; ++i) {
		cin >> state0[i];
	}

	// 题目给出了 9 种移动，每种移动会让若干个时钟同时顺时针转 90 度。
	// 这里把每个移动影响到的时钟下标预先存下来，方便后面暴力枚举时直接使用。
	const int affect[9][6] = {
			{0, 1, 3, 4, -1, -1},
			{0, 1, 2, -1, -1, -1},
			{1, 2, 4, 5, -1, -1},
			{0, 3, 6, -1, -1, -1},
			{1, 3, 4, 5, 7, -1},
			{2, 5, 8, -1, -1, -1},
			{3, 4, 6, 7, -1, -1},
			{6, 7, 8, -1, -1, -1},
			{4, 5, 7, 8, -1, -1}
	};

	vector<int> best;
	int bestStep = 1e9;

	// 每个移动最多按 3 次就会回到原状，所以 9 个移动都只需要枚举 0~3 次。
	// 这相当于暴力搜索 4^9 种方案，但规模很小，完全可以接受。
	for (int s1 = 0; s1 < 4; ++s1)
	for (int s2 = 0; s2 < 4; ++s2)
	for (int s3 = 0; s3 < 4; ++s3)
	for (int s4 = 0; s4 < 4; ++s4)
	for (int s5 = 0; s5 < 4; ++s5)
	for (int s6 = 0; s6 < 4; ++s6)
	for (int s7 = 0; s7 < 4; ++s7)
	for (int s8 = 0; s8 < 4; ++s8)
	for (int s9 = 0; s9 < 4; ++s9) {
		// press[i] 表示第 i+1 种移动按了多少次。
        int press[9] = {s1, s2, s3, s4, s5, s6, s7, s8, s9};
            // 拷贝一份初始状态，模拟当前方案是否能把所有时钟拨到 12 点。
        int state[9];
        for (int i = 0; i < 9; ++i) state[i] = state0[i];

            // 依次执行 1~9 号移动：每执行一次，就把它影响到的时钟加 1（mod 4）。
        for (int i = 0; i < 9; ++i) {
            for (int k = 0; affect[i][k] != -1; ++k) {
                state[affect[i][k]] = (state[affect[i][k]] + press[i]) % 4;
            }
        }

		// 如果 9 个时钟最终都变成 0，说明这一组按法可行。
        bool ok = true;
        for (int i = 0; i < 9; ++i) {
            if (state[i] != 0) {
                ok = false;
                break;
            }
        }
        if (!ok) continue;

		// 把“按了几次每个移动”展开成题目要求输出的序列，例如 3 次移动 4 就输出 4 4 4。
		vector<int> seq;
		int step = 0;
		for (int i = 0; i < 9; ++i) {
			step += press[i];
			for (int t = 0; t < press[i]; ++t) {
				seq.push_back(i + 1);
			}
		}

		// 先比总步数更少；若步数相同，vector 的字典序比较会自动选出更小的输出序列。
		if (step < bestStep || (step == bestStep && seq < best)) {
			bestStep = step;
			best = seq;
		}
	}

	// 按题目要求输出最短方案，多个数字之间用空格分隔。
	for (size_t i = 0; i < best.size(); ++i) {
		if (i) cout << ' ';
		cout << best[i];
	}
	cout << '\n';
	return 0;
}

/*
4个数算24，必有两个数要先算。
算的结果和剩余的两个数，就构成了3个数算24的问题。
所以可以用递归来解决这个问题。
*/
#include <iostream>
#include <cmath>
#include <iomanip>

using namespace std;
#define spacesize 4

const double eps = 1e-6;
double imputnums[spacesize+1];
bool iszero(double a) {
    return fabs(a) <= eps;
}

bool dfs(double nums[],int n) {
    if(n == 1) {
        if(iszero(nums[0]-24)) return true;
        else return false;
    }
    for(int i=0;i<n-1;i++)
      for(int j=i+1;j<n;j++){
        double temp[n-1]={0};
        int iTemp=0;
        for(int k=0;k<n;k++){
            if(k!=i && k!=j) temp[iTemp++] = nums[k];
        }
        temp[iTemp] = nums[i] + nums[j];
        if(dfs(temp,n-1)) return true;
        temp[iTemp] = nums[i] - nums[j];
        if(dfs(temp,n-1)) return true;
        temp[iTemp] = nums[j] - nums[i];
        if(dfs(temp,n-1)) return true;
        temp[iTemp] = nums[i] * nums[j];
        if(dfs(temp,n-1)) return true;
        if(!iszero(nums[j])) {
            temp[iTemp] = nums[i] / nums[j];
            if(dfs(temp,n-1)) return true;
        }
        if(!iszero(nums[i])) {
            temp[iTemp] = nums[j] / nums[i];
            if(dfs(temp,n-1)) return true;
        }
      }
    return false;
}

int main(){
    while(true){
        for(int i = 0; i < spacesize; ++i){
            cin >> imputnums[i];
        }
        if(iszero(imputnums[0]) && iszero(imputnums[1]) && iszero(imputnums[2]) && iszero(imputnums[3])) 
            break;
        if(dfs(imputnums,spacesize)) cout << "YES" << endl;
        else cout << "NO" << endl;
    }
}

