using namespace std;

int M,H,W;
int minMax[27][27][405];                    // 记忆化数组,把宽i,高j,切为m块的最大块体积值
const int Inf=0x3f3f3f3f,Inf2=0x7fffffff;   // Inf2表示无穷大,Inf表示无穷小

int dfs(int width,int height,int cutnumber)
{
    if(width*height<cutnumber+1) 
        return Inf;//如果切割块数大于总面积,返回无穷小
    if(cutnumber==0) 
        return width*height;
    if(minMax[width][height][cutnumber]!=-1) 
        return minMax[width][height][cutnumber];
    int MinMaxArea=Inf;

    for(int i=1;i<=width-1;i++)             //横向切割
    {
      for(int j=0;j<=cutnumber-1;j++)       //切割块数分配
      {
          int m1=dfs(i,height,j);           //左边块体积
          int m2=dfs(width-i,height,cutnumber-1-j); //右边块体积
          MinMaxArea=min(MinMaxArea,max(m1,m2));     //取最大块体积的最小值
      }
    }

    for(int i=1;i<=height-1;i++)            //纵向切割
    {
      for(int j=0;j<=cutnumber-1;j++)       
      {
          int m1=dfs(width,i,j);
          int m2=dfs(width,height-i,cutnumber-1-j);
          MinMaxArea=min(MinMaxArea,max(m1,m2));
      }
    }

    return minMax[width][height][cutnumber]=MinMaxArea;
}

int main(){
    while(true){
        cin>>W>>H>>M;
        if(W==0&&H==0&&M==0) break;
        memset(minMax,-1,sizeof(minMax));
        cout<<dfs(W,H,M-1)<<endl;
    }
    return 0;
}

#include <iostream>
#include <cmath>
#include <algorithm>
using namespace std;

int N, V, best = 0x3f3f3f3f;
int minV[25], minS[25];

void dfs(int dep, int sumV, int sumS, int prevR, int prevH) {
    if (dep == 0) {
        if (sumV == V) best = min(best, sumS);
        return;
    }
    // 剪枝
    if (sumV + minV[dep] > V) return;
    if (sumS + minS[dep] >= best) return;
    if (sumS + 2 * (V - sumV) / prevR >= best) return;

    for (int r = min(prevR - 1, (int)sqrt(V - sumV)); r >= dep; r--) {
        for (int h = min(prevH - 1, (V - sumV) / (r * r)); h >= dep; h--) {
            int addS = 2 * r * h;
            if (dep == N) addS += r * r;  // 底层加底面积
            dfs(dep - 1, sumV + r * r * h, sumS + addS, r, h);
        }
    }
}

int main() {
    cin >> N >> V;
    // 预计算最小体积和侧面积
    for (int i = 1; i <= N; i++) {
        minV[i] = minV[i-1] + i * i * i;
        minS[i] = minS[i-1] + 2 * i * i;
    }
    dfs(N, 0, 0, 100, 100);
    if (best == 0x3f3f3f3f) cout << 0 << endl;
    else cout << best << endl;
    return 0;
}

