#include <iostream>
#include <cstring>
using namespace std;
const int N=9;
//ones[i]表示i的二进制表示中1的个数
//LOG][i]表示只有一个1的二进制数i中1的位置
int ones[1<<N],LOG[1<<N];
int row[N],col[N],box[3][3];
string str;           //读入的字符串

int lowbit(int x){
    return x&-x;     //返回x的二进制表示中最低位的1
}

void init(){
    //初始化row和col的状态，二进制位为1表示该位的数字可用
    for(int i=0;i<N;i++) row[i]=col[i]=(1<<N)-1;
    //初始化box的状态，二进制位为1表示该位的数字可用
    for(int i=0;i<3;i++){
        for(int j=0;j<3;j++){
            box[i][j]=(1<<N)-1;
        }
    }
}

//求可选方案的交集
inline int get(int x,int y){
    //用&运算求并集
    return row[x]&col[y]&box[x/3][y/3];
}

bool dfs(int cnt){
    if(cnt==0) return true;

    int minV=10;
    int x,y;
    for(int i=0;i<N;i++){
        for(int j=0;j<N;j++){
            if(str[i*N+j]=='.'){
                int v=get(i,j);
                if(ones[v]<minV){
                    minV=ones[v];
                    x=i,y=j;
                }
            }
        }
    }
    for(int v=get(x,y);v;v-=lowbit(v)){
        int l=LOG[lowbit(v)];

        //修改状态
        row[x]-=(1<<l);
        col[y]-=(1<<l);
        box[x/3][y/3]-=(1<<l);
        str[x*N+y]=l+'1';  //填入数字

        if(dfs(cnt-1)) return true;

        //回溯
        row[x]+=(1<<l);
        col[y]+=(1<<l);
        box[x/3][y/3]+=(1<<l);
        str[x*N+y]='.';
    }

    return false;
}

int main(){
    for(int i=0;i<N;i++)
        LOG[1<<i]=i;  //初始化LOG数组

    //初始化ones数组
    for(int i=0;i<(1<<N);i++){
        int s=0;
        for(int j=i;j;j-=lowbit(j)) s++;  //计算i的二进制表示中1的个数
        ones[i]=s;                        //存储1的个数
    }

    while(cin>>str,str[0]!='e'){
        init();
        int cnt=0;
        for(int i=0,k=0;i<N;i++)
          for(int j=0;j<N;j++,k++){
              if(str[k]=='.') cnt++;  //统计空格的数量
              else{
                  int l=str[k]-'1';   //将字符转换为数字
                  row[i]-=(1<<l);     //更新行状态
                  col[j]-=(1<<l);     //更新列状态
                  box[i/3][j/3]-=(1<<l);//更新小方格状态
              }
          }
        dfs(cnt);
        cout<<str<<endl;  //输出结果
    }
    return 0;
}

