#include <iostream>
#include <vector>

using namespace std;

int initialState[9];
int currentState[9];
int pressCount[9];
vector<int> bestAnswer;
int bestStep = 1e9;

// 9 种移动分别会影响哪些时钟。
// 下标从 0 开始，-1 表示这一行已经没有更多元素了。
const int affect[9][6] = {
	{0, 1, 3, 4, -1, -1},
	{0, 1, 2, -1, -1, -1},
	{1, 2, 4, 5, -1, -1},
	{0, 3, 6, -1, -1, -1},
	{1, 3, 4, 5, 7, -1},
	{2, 5, 8, -1, -1, -1},
	{3, 4, 6, 7, -1, -1},
	{6, 7, 8, -1, -1, -1},
	{4, 5, 7, 8, -1, -1}
};

// 把第 move 个移动按 step 次后，对当前状态进行修改。
void applyMove(int move, int step) {
	for (int k = 0; affect[move][k] != -1; ++k) {
		int pos = affect[move][k];
		currentState[pos] = (currentState[pos] + step) % 4;
	}
}

// 深搜第 move 个移动，尝试它按 0~3 次的所有可能。
// 递归结束时，9 种移动都已经决定完，再检查当前方案是否可行。
void dfs(int move) {
	if (move == 9) {
		for (int i = 0; i < 9; ++i) {
			if (currentState[i] != 0) {
				return;
			}
		}

		vector<int> candidate;
		int totalStep = 0;
		for (int i = 0; i < 9; ++i) {
			totalStep += pressCount[i];
			for (int t = 0; t < pressCount[i]; ++t) {
				candidate.push_back(i + 1);
			}
		}

		// 先比较总步数，再比较输出序列字典序。
		if (totalStep < bestStep || (totalStep == bestStep && candidate < bestAnswer)) {
			bestStep = totalStep;
			bestAnswer = candidate;
		}
		return;
	}

	// 当前移动最多按 3 次就会回到原状，所以只需要枚举 0~3 次。
	for (int step = 0; step < 4; ++step) {
		pressCount[move] = step;
		applyMove(move, step);
		dfs(move + 1);
		// 回溯：撤销刚刚对状态做的修改，恢复到进入这一层递归前的样子。
		applyMove(move, (4 - step) % 4);
	}
}

int main() {
	for (int i = 0; i < 9; ++i) {
		cin >> initialState[i];
		currentState[i] = initialState[i];
	}

	dfs(0);

	for (size_t i = 0; i < bestAnswer.size(); ++i) {
		if (i) cout << ' ';
		cout << bestAnswer[i];
	}
	cout << '\n';
	return 0;
}

#include <iostream>
#include <algorithm>
using namespace std;

const int N=9,M=1<<N;   //M表示所有数字的状态，二进制位为1表示该位的数字可用
int ones[M],LOG[M];   
 //ones[i]表示i的二进制表示中1的个数
 //LOG[i]表示只有一个1的二进制数i中1的位置
 int row[N],col[N],block[3][3];
 int g[N][N];   //存储数独的数字
 int ans=-1;    //最大的分值

 //返回x的二进制表示中最低位的1所对应的数
 inline int lowbit(int x){
     return x&-x;   
 }

 void init(){
    //初始化LOG数组
    for(int i=0;i<N;i++){
        LOG[1<<i]=i;
    }
    //初始化ones数组
    for(int i=0;i<M;i++){
        ones[i]=ones[i>>1]+(i&1);
    }
    //初始化row、col、block的状态，二进制位为1表示该位的数字可用
    for(int i=0;i<N;i++) row[i]=col[i]=block[i/3][i%3]=M-1;   
    //初始化为111111111，表示1-9都可用

 }

 //求可选方案的交集
inline int get(int x,int y){
    //用&运算求并集
    return row[x]&col[y]&block[x/3][y/3];
}

inline int getScore(int x,int y,int t){
    return (min(min(x,8-x),min(y,8-y))+6)*t;   //分值计算公式
}

//设置现场和恢复现场的函数，t为正数表示设置现场，t为负数表示恢复现场
inline void set(int x,int y,int t){
    int s=1;
    if(t>0) g[x][y]=t;
    else{
        s=-1;
        t=-t;
        g[x][y]=0;
    }
    t--;

    row[x]-=(1<<t)*s;
    col[y]-=(1<<t)*s;
    block[x/3][y/3]-=(1<<t)*s;
}

void dfs(int cnt,int score){
    if(cnt==0){
        ans=max(ans,score);
        return;
    }
    int minV=10;     //minV表示当前可选方案中1的个数最少的方案
    int x,y;
    for(int i=0;i<N;i++){
        for(int j=0;j<N;j++){
            if(g[i][j]==0){
                int v=get(i,j);
                if(ones[v]<minV){
                    minV=ones[v];
                    x=i,y=j;
                }
            }
        }
    }
    for(int v=get(x,y);v;v-=lowbit(v)){     // 遍历所有可选方案
        int t=LOG[lowbit(v)]+1;
        set(x,y,t);   //设置现场
        dfs(cnt-1,score+getScore(x,y,t));
        set(x,y,-t);   //恢复现场
    }
}

int main(){
    init();
    int cnt=0,score=0;
    for(int i=0;i<N;i++)
      for(int j=0;j<N;j++){
        int t;
        cin>>t;
        if(t){
            set(i,j,t);
            score+=getScore(i,j,t);
        }
        else cnt++;
        }

    dfs(cnt,score);
    cout<<ans<<endl;
    return 0;
}

// 16x16 字母数独 (A~P) —— 位运算 + 约束传播 + MRV DFS
#include <iostream>
#include <string>
#include <cstring>
using namespace std;

const int N = 16;
typedef unsigned short mask_t;

int ones[1 << N], LOG[1 << N];
mask_t row[N], col[N], box[4][4];
string grid[N];

inline int lowbit(int x) { return x & -x; }

void init() {
    for (int i = 0; i < N; i++) LOG[1 << i] = i;
    for (int i = 1; i < (1 << N); i++) ones[i] = ones[i >> 1] + (i & 1);
}

//get 函数返回 (x, y) 位置的候选集，二进制位为 1 表示该位的数字可用
inline mask_t get(int x, int y) {
    return row[x] & col[y] & box[x / 4][y / 4];
}

// 在行/列中找隐形唯一数（传入的是排除已填格子后的候选集，已填格子的候选为 0）
bool hidden_single_in_unit(mask_t* cell_masks, bool is_row, int r, int c) {
    mask_t all = 0;
    for (int k = 0; k < N; k++) all |= cell_masks[k];

    for (mask_t v = all; v; v -= lowbit(v)) {
        mask_t bit = lowbit(v);
        int last = -1, cnt = 0;

        for (int k = 0; k < N && cnt <= 1; k++) {
            if (cell_masks[k] & bit) { cnt++; last = k; }
        }

        if (cnt == 1) {
            int x = is_row ? r : last;
            int y = is_row ? last : c;
            int l = LOG[bit];
            row[x] ^= bit; col[y] ^= bit; 
            box[x / 4][y / 4] ^= bit;
            grid[x][y] = 'A' + l;
            return true;
        }
    }
    return false;
}

// 在 4x4 宫中找隐形唯一数
bool hidden_single_in_box(int bx, int by) {
    mask_t cell_masks[N];
    int idx = 0;

    for (int i = bx * 4; i < bx * 4 + 4; i++)
        for (int j = by * 4; j < by * 4 + 4; j++)
            cell_masks[idx++] = (grid[i][j] == '-') ? get(i, j) : 0;

    mask_t all = 0;
    for (int k = 0; k < N; k++) all |= cell_masks[k];
    for (mask_t v = all; v; v -= lowbit(v)) {
        mask_t bit = lowbit(v);
        int last = -1, cnt = 0;

        for (int k = 0; k < N && cnt <= 1; k++) {
            if (cell_masks[k] & bit) { cnt++; last = k; }
        }
        if (cnt == 1) {
            int x = bx * 4 + last / 4, y = by * 4 + last % 4;
            int l = LOG[bit];
            row[x] ^= bit; col[y] ^= bit; box[x / 4][y / 4] ^= bit;
            grid[x][y] = 'A' + l;
            return true;
        }
    }
    return false;
}

// 约束传播：裸唯一数 + 隐形唯一数
bool propagate() {
    bool changed = true;
    while (changed) {
        changed = false;
        // 裸唯一数
        for (int i = 0; i < N; i++)
            for (int j = 0; j < N; j++)
                if (grid[i][j] == '-') {
                    mask_t cand = get(i, j);
                    if (cand == 0) return false;
                    if (ones[cand] == 1) {      // 只有一个候选数
                        int l = LOG[cand];      // 写进盘面
                        //更新状态
                        row[i] ^= cand; 
                        col[j] ^= cand; 
                        box[i/4][j/4] ^= cand;
                        grid[i][j] = 'A' + l;
                        changed = true;
                    }
                }
        // 行隐形唯一数（跳过已填格子）
        for (int i = 0; i < N; i++) {
            mask_t unit[N];
            for (int j = 0; j < N; j++)
                unit[j] = (grid[i][j] == '-') ? get(i, j) : 0;
            if (hidden_single_in_unit(unit, true, i, -1)) changed = true;
        }
        // 列隐形唯一数
        for (int j = 0; j < N; j++) {
            mask_t unit[N];
            for (int i = 0; i < N; i++)
                unit[i] = (grid[i][j] == '-') ? get(i, j) : 0;
            if (hidden_single_in_unit(unit, false, -1, j)) changed = true;
        }
        // 宫隐形唯一数
        for (int bx = 0; bx < 4; bx++)
            for (int by = 0; by < 4; by++)
                if (hidden_single_in_box(bx, by)) changed = true;
    }
    return true;
}

bool dfs(int cnt) {
    if (cnt == 0) return true;

    // MRV
    int minV = N + 1, x = 0, y = 0;  
    // minV 表示当前可选方案中 1 的个数最少的方案

    for (int i = 0; i < N && minV > 1; i++)
        for (int j = 0; j < N && minV > 1; j++)
            if (grid[i][j] == '-') {
                mask_t v = get(i, j);
                if (ones[v] < minV) { minV = ones[v]; x = i, y = j; }
            }

    // 备份现场
    mask_t state = get(x, y);           
    string backup[N];                   
    mask_t brow[N], bcol[N], bbox[4][4];
    // 备份行/列/宫的状态
    for (int i = 0; i < N; i++) { 
        backup[i] = grid[i]; brow[i] = row[i]; 
        bcol[i] = col[i]; 
    }

    for (int i = 0; i < 4; i++) for (int j = 0; j < 4; j++) 
        bbox[i][j] = box[i][j];

    //遍历所有可选方案
    for (mask_t v = state; v; v -= lowbit(v)) {
        mask_t bit = lowbit(v);// 取出最低位的 1
        int l = LOG[bit];      // l表示当前尝试放置的数字（0~15 对应 A~P）
        // 还原
        for (int i = 0; i < N; i++) { 
            grid[i] = backup[i]; row[i] = brow[i]; 
            col[i] = bcol[i]; 
        }

        for (int i = 0; i < 4; i++) 
          for (int j = 0; j < 4; j++) 
            box[i][j] = bbox[i][j];

        // 放置
        row[x] ^= bit; col[y] ^= bit; 
        box[x / 4][y / 4] ^= bit;
        grid[x][y] = 'A' + l;
        if (!propagate()) continue;// 约束传播失败，回溯

        int rem = 0;// 计算剩余空格数
        for (int i = 0; i < N; i++)
            for (int j = 0; j < N; j++)
                if (grid[i][j] == '-') rem++;
        if (dfs(rem)) return true;
    }
    return false;
}

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    init();

    string line;
    bool first = true;
    while (true) {
        int idx = 0;
        while (idx < 16) {                  // 读取 16x16 字母数独
            if (!getline(cin, line)) break;
            if (line.empty()) continue;     // 跳过空行
            grid[idx++] = line;
        }
        if (idx == 0) break;                

        for (int i = 0; i < N; i++)         // 初始化行/列/宫的候选集
            row[i] = col[i] =box[i/4][i%4]= (1 << N) - 1;

        int cnt = 0;
        for (int i = 0; i < N; i++)
            for (int j = 0; j < N; j++)
                if (grid[i][j] == '-') cnt++;
                else {
                    int t = grid[i][j] - 'A';
                    //放置
                    row[i] ^= (1 << t); col[j] ^= (1 << t); box[i/4][j/4] ^= (1 << t);
                }

        if (!propagate()) {
            // 矛盾，不应发生（题目保证唯一解）
            continue;
        }

        cnt = 0;
        for (int i = 0; i < N; i++)
            for (int j = 0; j < N; j++)
                if (grid[i][j] == '-') cnt++;
        dfs(cnt);

        if (!first) cout <<endl;
        first = false;
        for (int i = 0; i < N; i++)
            cout << grid[i] << endl;
    }
    return 0;
}

#include  <iostream>
#include  <iomanip>
#include  <cstdio>
#include <cstring>

using namespace std;

const int N=20000;

char g[20][20];
int m=16*16*4;
int u[N],d[N],l[N],r[N],s[N],col[N],row[N],idx;
int ans[N],top;
//idx表示当前节点的编号，row[i]表示第i个节点所在的行，
//col[i]表示第i个节点所在的列，s[i]表示第i列的节点数，
//u[i]表示第i个节点上方的节点编号，d[i]表示第i个节点下方的节点编号，
//l[i]表示第i个节点左边的节点编号，r[i]表示第i个节点右边的节点编号。

// 每一个候选填法对应一行，每一条约束对应一列。
// 这题是 16x16 字母数独：
// 1. 每个格子必须填一个字母
// 2. 每一行每个字母只能出现一次
// 3. 每一列每个字母只能出现一次
// 4. 每个 4x4 宫每个字母只能出现一次
struct Op{
    int x,y;
    char z;
}op[N];

// 初始化 DLX 的“列头”循环链表。
// 0 号点是总头结点，1..m 是各个约束列。
void init(){
    for(int i=0;i<=m;i++){
        l[i]=i-1;
        r[i]=i+1;
        s[i]=0;
        d[i]=u[i]=i; 
    }
    l[0]=m;r[m]=0;// 形成循环链表
    idx=m+1;        
}

// 往 DLX 里加入一个节点：
// x 表示“这个候选答案的编号”，y 表示“它满足了哪一列约束”。
// hh / tt 用来维护同一行上的左右链。
void add(int &hh,int &tt,int x,int y){
    row[idx]=x;col[idx]=y;s[y]++;
    //记录当前新节点属于第 x 个候选行
    //它满足第 y 列约束
    //s[y] 表示这一列现在有多少个节点，所以要加 1

    u[idx]=y;d[idx]=d[y];u[d[y]]=idx;d[y]=idx;
    //把新节点插进“第 y 列”的竖向双向链表里
    //可以理解成：把它插到列头 y 的下面

    r[hh]=l[tt]=idx;
    //把新节点接到“当前这一行”的左右链上
    //hh和tt是这一行当前的左端和右端

    r[idx]=tt;l[idx]=hh;
    //让新节点和行里的前后节点互相指向
    //这样这一行就形成了一个循环双向链表

    tt=idx++;
    //把当前行的尾指针更新成这个新节点
    //然后 idx 自增，准备下一个节点
}

// 删除一列，以及该列中所有相关行的其它列节点。
// 这一步就是 DLX 里的 cover。
void remove(int p){

    // 先把列头 p 从“列头循环链表”里摘掉，表示这一列暂时不再参与搜索。
    r[l[p]]=r[p];l[r[p]]=l[p];

    // 遍历这一列中的每一个节点，也就是所有满足这个约束的候选行。
    for(int i=d[p];i!=p;i=d[i]){
        // 对于这一行里的其它节点，把它们所在的列也删掉。
        // 因为如果这一行被选中，这些列就已经被占用了，不能再和别的候选冲突。
        for(int j=r[i];j!=i;j=r[j]){
            // 从纵向链表中删除节点 j。
            // 同时 s[col[j]]-- 表示这一列剩下的候选数减 1，便于后面选择最优列。
            u[d[j]]=u[j];d[u[j]]=d[j];
            s[col[j]]--;
        }
    }
}

// 还原一列，以及之前被删掉的相关节点。
// 这一步就是 DLX 里的 uncover。
void resume(int p){
    // 和 remove() 的过程正好相反：
    // 先从下面往上遍历这一列中的节点，把当初删掉的节点逐个恢复回来。
    for(int i=u[p];i!=p;i=u[i]){
        // 对这一行来说，之前被删掉的是它右边的那些列节点，
        // 现在要按相反方向从左往右恢复，保证链表结构和删除前一致。
        for(int j=l[i];j!=i;j=l[j]){
            // 把节点 j 重新挂回它所在的纵向链表中：
            // u[d[j]] 和 d[u[j]] 原来指向的是 j 断开后留下的上下邻居，
            // 这里把它们重新接回去。
            u[d[j]]=j;d[u[j]]=j;
            // 这一列的候选数恢复 1，表示这个位置又重新可用了。
            s[col[j]]++;
        }
    }
    // 最后把列头 p 重新接回列头循环链表，表示这一列重新参与搜索。
    l[r[p]]=p;r[l[p]]=p;
}

// 经典 DLX 搜索：
// 每次选择当前“候选数最少”的列，优先剪枝。
bool dfs(){
    // 如果没有列了，说明所有约束都满足了，找到一个解。
    if(!r[0]) return true;
    int p=r[0];// 选择当前候选数最少的列 p

    // 遍历这一列中的每一个节点，也就是所有满足这个约束的候选行。
    for(int i=r[0];i;i=r[i]) 
        if(s[i]<s[p]) p=i;// 找到候选数最少的列 p
    remove(p);// 把列 p 从链表中摘掉，表示暂时不再考虑这个约束

    // 遍历这一列中的每一个节点，也就是所有满足这个约束的候选行。
    for(int i=d[p];i!=p;i=d[i]){
        ans[++top]=row[i];// 记录当前选择的候选行编号

        // 对于这一行里的其它节点，把它们所在的列也删掉。
        for(int j=r[i];j!=i;j=r[j]) remove(col[j]);
        if(dfs()) return true;

        // 回溯：如果 dfs() 返回 false，说明当前选择的候选行不行，需要撤销选择。
        for(int j=l[i];j!=i;j=l[j]) resume(col[j]);
        top--;
    }
    resume(p);
    return false;
}

int main(){
    while(~scanf("%s",g[0])){
        for(int i=1;i<16;i++) scanf("%s",g[i]);
        init();

        // 枚举每个空格的所有候选字母，把“格子 / 行字母 / 列字母 / 宫字母”
        // 这四类约束都转成精确覆盖的列。
        for(int i=0,n=1;i<16;i++){
            for(int j=0;j<16;j++){
                int a=0,b=15;
                if(g[i][j]!='-'){
                    a=g[i][j]-'A';
                    b=a;
                }
                for(int k=a;k<=b;k++){
                    int hh=idx,tt=idx;// hh 和 tt 用来维护同一行上的左右链。
                    op[n]={i,j,char(k+'A')};
                    add(hh,tt,n,i*16+j+1);// 格子约束
                    add(hh,tt,n,256+i*16+k+1);// 行字母约束
                    add(hh,tt,n,256*2+j*16+k+1);// 列字母约束
                    add(hh,tt,n,256*3+(i/4*4+j/4)*16+k+1);// 宫字母约束
                    n++;
                }
            }
        }

        // 搜索出一组满足所有约束的候选行，回填到棋盘。
        dfs();
        for(int i=1;i<=top;i++){
            auto t=op[ans[i]];
            g[t.x][t.y]=t.z;
        }
        for(int i=0;i<16;i++) printf("%s\n",g[i]);
    }
}
